public static long calculateTotalPossibleVariants() {
    long basePalettes = PALETTE_REGISTRY.size();
    long overlayPatterns = OVERLAY_PATTERN_NAMES.size() - 1;
    long visualEyeStates = EYE_GENOTYPE_NAMES.stream().filter(name -> !name.contains("carrier")).count();
    long visuallyDistinct = 0L;
    for (PaletteDefinition baseDef : PALETTE_REGISTRY.values()) {
        ArrayList<HamsterColorZone> allowedWildZones = new ArrayList<HamsterColorZone>(ConfigDataCache.getAllowedWildOverlayZones());
        allowedWildZones.remove((Object)baseDef.zone());
        if (ConfigDataCache.getRestrictedBaseZones().contains((Object)baseDef.zone())) {
            allowedWildZones.removeAll(ConfigDataCache.getClashingOverlayZones());
        }
        long validWildOverlays = PALETTE_REGISTRY.values().stream().filter(p -> allowedWildZones.contains((Object)p.zone())).filter(p -> HamsterGeneticsUtil.isValidWildOverlay(baseDef, p)).count();
        long validBreedingPalettes = PALETTE_REGISTRY.values().stream().filter(p -> HamsterGeneticsUtil.isValidBreedingOverlay(baseDef, p)).count();
        long noWildOverlayStates = 1L;
        long breedingCombsIfNoWild = 1L + validBreedingPalettes * overlayPatterns;
        long totalNoWildBranch = noWildOverlayStates * breedingCombsIfNoWild;
        long withWildOverlayStates = validWildOverlays * overlayPatterns;
        long breedingCombsIfWild = 1L + validBreedingPalettes * (overlayPatterns - 1L);
        long totalWithWildBranch = withWildOverlayStates * breedingCombsIfWild;
        visuallyDistinct += (totalNoWildBranch + totalWithWildBranch) * visualEyeStates;
    }
    return visuallyDistinct;
}

public static PaletteDefinition getClosestPalette(Vec3 targetPos, Set<String> exclusions, Set<HamsterColorZone> allowedZones, boolean requireProgrammatic) {
    PaletteDefinition closest = null;
    double minDistance = Double.MAX_VALUE;
    for (PaletteDefinition def : PALETTE_REGISTRY.values()) {
        double dist;
        if (exclusions != null && exclusions.contains(def.id()) || allowedZones != null && !allowedZones.contains((Object)def.zone()) || requireProgrammatic && def.type() != TextureType.PROGRAMMATIC || !((dist = ColorSpaceUtil.getColorDistance(targetPos, def.colorSpacePos())) < minDistance)) continue;
        minDistance = dist;
        closest = def;
    }
    if (closest == null && !PALETTE_REGISTRY.isEmpty()) {
        return PALETTE_REGISTRY.values().iterator().next();
    }
    return closest;
}

public static PaletteDefinition getRandomPalette(RandomSource random, Set<HamsterColorZone> allowedZones, boolean requireProgrammatic) {
    ArrayList<PaletteDefinition> valid = new ArrayList<PaletteDefinition>();
    for (PaletteDefinition def : PALETTE_REGISTRY.values()) {
        if (allowedZones != null && !allowedZones.contains((Object)def.zone()) || requireProgrammatic && def.type() != TextureType.PROGRAMMATIC) continue;
        valid.add(def);
    }
    if (valid.isEmpty()) {
        return PALETTE_REGISTRY.values().iterator().next();
    }

