public static final List<String> BASE_PATTERN_NAMES = List.of("fur_pattern");
public static final List<String> OVERLAY_PATTERN_NAMES = List.of("none", "splotched_body", "body", "overlay_spots", "belly", "torso_fold", "torso_wrap", "splotched_ears", "inverted_spots", "piebald", "panda");
public static final List<String> EYE_GENOTYPE_NAMES = List.of("black", "carrier_black", "red");
private static boolean initialReportPrinted = false;

public static void init() {
    PALETTE_REGISTRY.clear();
    HamsterPaletteManager.registerProgrammatic("cream", CREAM);
    HamsterPaletteManager.registerProgrammatic("white", WHITE);
    HamsterPaletteManager.registerProgrammatic("black", BLACK);
    HamsterPaletteManager.registerProgrammatic("blue", BLUE);
    HamsterPaletteManager.registerProgrammatic("lavender", LAVENDER);
    HamsterPaletteManager.registerProgrammatic("light_gray", LIGHT_GRAY);
    HamsterPaletteManager.registerProgrammatic("dark_gray", DARK_GRAY);
    HamsterPaletteManager.registerProgrammatic("chocolate", CHOCOLATE);
    HamsterPaletteManager.registerProgrammatic("orange", ORANGE);
    for (Map.Entry<String, List<String>> entry : COMMUNITY_TEXTURES.entrySet()) {
        String author = entry.getKey();
        for (String textureName : entry.getValue()) {
            HamsterPaletteManager.registerStatic(author, textureName);
        }
    }
    double minBri = Double.MAX_VALUE;
    double maxSat = Double.MIN_VALUE;
    for (PaletteDefinition paletteDefinition : PALETTE_REGISTRY.values()) {
        double bri = ColorSpaceUtil.getBrightness(paletteDefinition.colorSpacePos());
        double sat = ColorSpaceUtil.getSaturation(paletteDefinition.colorSpacePos());
        if (bri < minBri) {
            minBri = bri;
        }
        if (!(sat > maxSat)) continue;
        maxSat = sat;
    }
    for (Map.Entry entry : PALETTE_REGISTRY.entrySet()) {
        PaletteDefinition oldDef = (PaletteDefinition)entry.getValue();
        float normalizedDiluteness = ColorSpaceUtil.calculateNormalizedDiluteness(oldDef.colorSpacePos(), minBri, maxSat);
        PaletteDefinition newDef = new PaletteDefinition(oldDef.id(), oldDef.author(), oldDef.type(), oldDef.hexCodes(), oldDef.colorSpacePos(), normalizedDiluteness, oldDef.zone());
        PALETTE_REGISTRY.put((String)entry.getKey(), newDef);
    }
}

public static void triggerInitialReport() {
    if (!initialReportPrinted) {
        HamsterPaletteManager.printGeneticsReport(null, false);
        initialReportPrinted = true;
    }
}

